#include "des_schedule.h"
int main(void){char in[64];uint64_t key,ks[16];uint32_t c[17],d[17];printf("Enter 16 hexadecimal digits for the 64-bit DES key: ");if(scanf("%63s",in)!=1)return 1;if(!des_parse_hex64(in,&key)){puts("Invalid hex key.");return 1;}des_make_subkeys(key,ks,c,d);puts("Round | Cn (28 bits) | Dn (28 bits) | first 24 subkey bits (from Cn) | last 24 (from Dn)");for(int i=0;i<16;i++)printf("%2d    | %07X | %07X | %06llX | %06llX\n",i+1,c[i+1],d[i+1],(unsigned long long)((ks[i]>>24)&0xffffff),(unsigned long long)(ks[i]&0xffffff));puts("PC-2 selects 24 bits from the rotated C half and 24 from the rotated D half, forming the 48-bit subkey.");return 0;}
